insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:burnley-football-club:cynosure-checketts-sports-capital:november-2025', null, 'November 2025', 'minority_investment', 'sports', 'football', 'Burnley Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--burnley'), null, 'Cynosure | Checketts Sports Capital', 'private_equity', (select id from public.companies where lower(name) = lower('Cynosure | Checketts Sports Capital') limit 1), (select id from public.sports_investors where lower(name) = lower('Cynosure | Checketts Sports Capital') limit 1), null, null, 200000000, 'USD', null, null, 'Cynosure | Checketts Sports Capital invests $200m-plus in Burnley parent ALK Capital', 'Dave Checketts'' newly launched private equity fund Cynosure | Checketts Sports Capital Fund I made its first investment, upwards of $200m into ALK Capital, the parent of Burnley and Espanyol. The capital is to fund ALK''s football operations across both clubs.', 'ALK Capital', 'https://alkcapital.com/2025/11/alk-capital-and-cynosure-checketts-sports-capital-reunite-in-significant-strategic-investment-across-european-football/', 'web_research')
