  values ('deal:chelsea-football-club:consortium-led-by-todd-boehly-and-clearlake-capital-with-mark-walter-hansjorg-wy:2022-05-30', '2022-05-30', '30 May 2022', 'acquisition', 'sports', 'football', 'Chelsea Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--chelsea'), null, 'Consortium led by Todd Boehly and Clearlake Capital (with Mark Walter, Hansjörg Wyss)', 'consortium', (select id from public.companies where lower(name) = lower('Consortium led by Todd Boehly and Clearlake Capital (with Mark Walter, Hansjörg Wyss)') limit 1), (select id from public.sports_investors where lower(name) = lower('Consortium led by Todd Boehly and Clearlake Capital (with Mark Walter, Hansjörg Wyss)') limit 1), 'Roman Abramovich', 100, 2500000000, 'GBP', 4250000000, 'GBP', 'Boehly-Clearlake consortium completes £4.25bn takeover of Chelsea', 'A consortium led by Todd Boehly and Clearlake Capital completed the purchase of Chelsea from Roman Abramovich, who was forced to sell after UK sanctions. £2.5bn was paid for the shares with a further £1.75bn committed for investment, giving a headline value of £4.25bn. Clearlake took the majority shareholding while Boehly and Clearlake shared joint control.', 'ESPN', 'https://www.espn.com/soccer/story/_/id/37628834/todd-boehly-completes-chelsea-takeover-deal-worth-425bn', 'web_research')
